/bin/bash -lc "python3 -m py_compile /workspace/openai_client.py && python3 - <<'PY'
import openai_client
sample = {\"output\": [{\"type\": \"message\", \"content\": [{\"type\": \"output_text\", \"text\": \"ok\"}]}]}
assert openai_client.response_text(sample) == \"ok\"
try:
    openai_client.responses_create(\"\", api_key=\"not-used\")
except ValueError:
    pass
else:
    raise AssertionError(\"empty prompt was accepted\")
print(\"module checks passed\")
PY"

